CREATE TABLE IF NOT EXISTS members(id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, password VARCHAR(100) NOT NULL, role VARCHAR(12) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL REFERENCES members(id), title VARCHAR(120) NOT NULL, content VARCHAR(2800) NOT NULL, channel VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, due_at BIGINT NOT NULL, created_at BIGINT NOT NULL, published_at BIGINT, generation INTEGER NOT NULL DEFAULT 0, fail_demo BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS outbox(id VARCHAR(80) PRIMARY KEY, post_id VARCHAR(36) NOT NULL REFERENCES posts(id), due_at BIGINT NOT NULL, sent BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS publications(post_id VARCHAR(36) PRIMARY KEY REFERENCES posts(id), published_at BIGINT NOT NULL, content VARCHAR(2800) NOT NULL);
CREATE TABLE IF NOT EXISTS comments(id VARCHAR(36) PRIMARY KEY, post_id VARCHAR(36) NOT NULL REFERENCES posts(id), author_id VARCHAR(36) NOT NULL REFERENCES members(id), body VARCHAR(800) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id VARCHAR(36) PRIMARY KEY, message VARCHAR(200) NOT NULL, created_at BIGINT NOT NULL);
